CREATE OR ALTER PROCEDURE [dbo].[uspCustomerDeliveryLocation_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @Code NVARCHAR(MAX) = NULL
	, @Name NVARCHAR(MAX) = NULL
	, @Address NVARCHAR(MAX) = NULL
	, @ContactName NVARCHAR(MAX) = NULL
	, @ContactPhone NVARCHAR(MAX) = NULL
	, @DeliveryInstructions NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CustomerId]
			, t.[Code]
			, t.[Name]
			, t.[Address]
			, t.[ContactName]
			, t.[ContactPhone]
			, t.[Latitude]
			, t.[Longitude]
			, t.[DeliveryWindowFrom]
			, t.[DeliveryWindowTo]
			, t.[Status]
			, t.[DeliveryInstructions]
			, t.[CreatedDate]
		FROM [dbo].[CustomerDeliveryLocation] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%') OR t.[ContactName] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (ISNULL(@Address, '') = '' OR t.[Address] LIKE CONCAT('%', @Address, '%'))
			AND (ISNULL(@ContactName, '') = '' OR t.[ContactName] LIKE CONCAT('%', @ContactName, '%'))
			AND (ISNULL(@ContactPhone, '') = '' OR t.[ContactPhone] LIKE CONCAT('%', @ContactPhone, '%'))
			AND (ISNULL(@DeliveryInstructions, '') = '' OR t.[DeliveryInstructions] LIKE CONCAT('%', @DeliveryInstructions, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'address' THEN r.[Address] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'address' THEN r.[Address] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contactName' THEN r.[ContactName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contactName' THEN r.[ContactName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contactPhone' THEN r.[ContactPhone] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contactPhone' THEN r.[ContactPhone] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'latitude' THEN r.[Latitude] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'latitude' THEN r.[Latitude] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'longitude' THEN r.[Longitude] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'longitude' THEN r.[Longitude] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryWindowFrom' THEN r.[DeliveryWindowFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryWindowFrom' THEN r.[DeliveryWindowFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryWindowTo' THEN r.[DeliveryWindowTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryWindowTo' THEN r.[DeliveryWindowTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryInstructions' THEN r.[DeliveryInstructions] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryInstructions' THEN r.[DeliveryInstructions] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
